--
--  HOW TO USE THIS FILE
--
--    1. In Neon, open your project, then "SQL Editor" in the left sidebar.
--    2. Open this file in any plain text editor, select all, copy.
--    3. Paste it into the SQL editor and press Run.
--
--  You should see "Success" (or "APPLIED"). Running it a second time is safe:
--  it will say "Already applied — nothing to do" and skip the rest.
--
--  The whole file runs as one transaction. If any line fails, nothing at all
--  is applied and your database is left exactly as it was.

--  Makes admin@shopyangu.co.ke a platform admin.
--
--  A platform admin can sign in at /admin/ and see every shop on the platform,
--  and pause one. They cannot read any shop's sales, products or customers —
--  that stays with the shop's own owner.
-- ============================================================================

create table if not exists app_schema (
  file       text primary key,
  applied_at timestamptz not null default now(),
  checksum   text
);

begin;

do $mig$
begin
  if exists (select 1 from app_schema where file = 'apply-super-admin.sql' and checksum = '7afbc9661fc3f26d') then
    raise notice 'Already applied — nothing to do.';
    return;
  end if;

create or replace function create_super_admin(p_email text, p_name text default 'Super admin')
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  insert into logins (shop_id, email, name, role, email_verified_at)
  values (null, p_email, p_name, 'super_admin', now())
  on conflict (email) do update
    set role = 'super_admin', shop_id = null, email_verified_at = coalesce(logins.email_verified_at, now())
  returning id into v_id;

  return v_id;
end;
$$;

  perform create_super_admin('admin@shopyangu.co.ke', 'Platform admin');

  delete from app_schema where file = 'apply-super-admin.sql';
  insert into app_schema (file, checksum, applied_at) values ('apply-super-admin.sql', '7afbc9661fc3f26d', now());
  raise notice 'APPLIED.';
end
$mig$;

commit;
